	     (bit(reg, 2) << 0);
    /* Save bits used to feed bit 0 */
    bit22= bit(reg,22);
    bit17= bit(reg,17);
    /* Shift 1 bit left */
    reg= reg << 1;
    /(* Feed bit 0 */
    reg= reg | (bit22 ^ bit17);
  };
};

