        .if (val.getType()==AT_IMMEDIATE) {
            .byte $c9, <val.getValue(), >val.getValue()
        }
        .if (val.getType()==AT_ABSOLUTE) {
            .if (val.getValue()<256) {
                .byte $c5, <val.getValue()  // Direct Page
            } else {
                .if (val.getValue()<65536) {
                    .byte $cd, <val.getValue(), >val.getValue()
