            .byte $d9, <val.getValue(), >val.getValue()
        }
        .if (val.getType()==AT_IZEROPAGEX) {
            cmp (val.getValue(),x)
        }
        .if (val.getType()==AT_IZEROPAGEY) {
            cmp (val.getValue()),y
        }
        .if (val.getType()==AT_INDIRECT) {
            .byte $d2, val.getValue()
        }
    }
